pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    assert!(tol > 0, "tolerance must be strictly positive");

    // Compute in i16 to avoid i8 overflow on subtraction/negation.
    let diff: i16 = a as i16 - b as i16;
    let t: i16 = tol as i16;

    diff > -t && diff < t
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert!(!a.is_empty(), "input length must be positive");
    assert_eq!(a.len(), b.len(), "input arrays must have equal length");
    assert!(tol > 0, "tolerance must be strictly positive");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(ai, bi)| is_close_i8(ai, bi, tol))
        .collect()
}